initJs:
function(container, apiUrl, tables) {
  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  let currentOrderData = [];
  let storeData = [];
  let productData = [];
  let demandForecastData = [];

  // 店舗データを読み込み
  async function loadStoreData() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      storeData = stores.filter(s => s.有効フラグ);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      storeData.forEach(store => {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      });
    }
  }

  // 商品データを読み込み
  async function loadProductData() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      productData = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
    }
  }

  // 需要予測データを読み込み
  async function loadDemandForecastData() {
    const forecasts = await window.aivicApi.list(8); // 需要予測結果
    if (forecasts) {
      demandForecastData = forecasts;
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 発注データテーブル再描画
  function renderOrderTable(data) {
    const tbody = container.querySelector('#order-table-body');

    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="muted" style="text-align: center; padding: 40px;">データがありません</td></tr>';
      updateSummary();
      return;
    }

    tbody.innerHTML = data.map(item => `
      <tr data-id="${item.商品ID}">
        <td>
          <input type="checkbox" class="order-checkbox" data-product-id="${item.商品ID}" />
        </td>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td>${item.予測数量 || 0}</td>
        <td>${item.推奨発注数量 || 0}</td>
        <td>${item.現在在庫数量 || 0}</td>
        <td>
          <input type="number" class="quantity-input" data-product-id="${item.商品ID}" 
                 value="${item.推奨発注数量 || 0}" min="0" max="9999" />
          <div class="error-text hidden" id="error-${item.商品ID}"></div>
        </td>
        <td>¥${(item.発注単価 || 0).toLocaleString()}</td>
        <td class="order-amount" data-product-id="${item.商品ID}">¥${((item.推奨発注数量 || 0) * (item.発注単価 || 0)).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary single-order-btn" data-product-id="${item.商品ID}">発注実行</button>
        </td>
      </tr>
    `).join('');

    // 数量変更時の金額計算
    tbody.querySelectorAll('.quantity-input').forEach(input => {
      input.addEventListener('input', function() {
        const productId = this.dataset.productId;
        const quantity = parseInt(this.value) || 0;
        const product = currentOrderData.find(p => p.商品ID === productId);

        if (product) {
          const amount = quantity * (product.発注単価 || 0);
          const amountCell = container.querySelector(`.order-amount[data-product-id="${productId}"]`);
          if (amountCell) {
            amountCell.textContent = `¥${amount.toLocaleString()}`;
          }
        }

        updateSummary();
        validateQuantity(this);
      });

      input.addEventListener('blur', function() {
        validateQuantity(this);
      });
    });

    // チェックボックス変更時の処理
    tbody.querySelectorAll('.order-checkbox').forEach(checkbox => {
      checkbox.addEventListener('change', function() {
        updateSummary();
        updateBulkOrderButton();
      });
    });

    updateSummary();
    updateBulkOrderButton();
  }

  // 数量バリデーション
  function validateQuantity(input) {
    const errorDiv = container.querySelector(`#error-${input.dataset.productId}`);
    const value = input.value.trim();

    // エラー状態をリセット
    input.classList.remove('error-input');
    errorDiv.classList.add('hidden');
    errorDiv.textContent = '';

    if (value === '') {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (!/^\d+$/.test(value)) {
      input.classList.add('error-input');
      errorDiv.textContent = '数値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    const quantity = parseInt(value);
    if (quantity < 0) {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量は正の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity === 0) {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量は1以上の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity > 9999) {
      input.classList.add('error-input');
      errorDiv.textContent = '発注数量は9999以下で入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    return true;
  }

  // サマリー更新
  function updateSummary() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked');
    const selectedCount = checkboxes.length;

    let totalAmount = 0;
    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;
      const product = currentOrderData.find(p => p.商品ID === productId);
      if (product) {
        totalAmount += quantity * (product.発注単価 || 0);
      }
    });

    container.querySelector('#selected-count').textContent = selectedCount;
    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
  }

  // まとめて発注ボタンの状態更新
  function updateBulkOrderButton() {
    const selectedCount = container.querySelectorAll('.order-checkbox:checked').length;
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');
    bulkOrderBtn.disabled = selectedCount === 0;
  }

  // 発注データ作成
  function createOrderData(storeId, orderDate) {
    if (!storeId || !orderDate) return [];

    const orderData = [];
    const selectedDate = new Date(orderDate);

    // 選択店舗の需要予測データを取得
    const storeForecast = demandForecastData.filter(f => 
      f.店舗ID === storeId && 
      new Date(f.予測対象日).toDateString() === selectedDate.toDateString()
    );

    // 商品マスタと需要予測を結合
    productData.forEach(product => {
      const forecast = storeForecast.find(f => f.商品ID === product.商品ID);
      const predictedQuantity = forecast ? forecast.予測数量 : 0;
      const recommendedQuantity = forecast ? forecast.推奨発注数量 : 0;

      // 現在在庫数量（ダミーデータ）
      const currentStock = Math.floor(Math.random() * 100) + 10;

      orderData.push({
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        商品カテゴリ: getProductCategory(product.商品カテゴリID),
        予測数量: predictedQuantity,
        推奨発注数量: recommendedQuantity,
        現在在庫数量: currentStock,
        発注単価: product.単価
      });
    });

    return orderData;
  }

  // 商品カテゴリ名取得（簡易実装）
  function getProductCategory(categoryId) {
    const categories = {
      'cat1': '食品',
      'cat2': '日用品',
      'cat3': '衣料品',
      'cat4': '家電'
    };
    return categories[categoryId] || '食品';
  }

  // 表示更新
  async function updateDisplay() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const categoryFilter = container.querySelector('#category-filter').value;

    if (!storeId) {
      renderOrderTable([]);
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    // 過去日付チェック
    const selectedDate = new Date(orderDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selectedDate < today) {
      showError('発注日付は本日以降の日付を選択してください');
      return;
    }

    let orderData = createOrderData(storeId, orderDate);

    // カテゴリフィルター適用
    if (categoryFilter) {
      orderData = orderData.filter(item => item.商品カテゴリ === categoryFilter);
    }

    currentOrderData = orderData;
    renderOrderTable(orderData);
  }

  // 発注実行
  async function executeOrder(orderItems) {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    const results = [];

    for (const item of orderItems) {
      const orderData = {
        店舗ID: storeId,
        商品ID: item.商品ID,
        発注日: new Date(orderDate).toISOString(),
        納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
        発注数量: item.発注数量,
        予測数量: item.予測数量,
        発注単価: item.発注単価,
        発注金額: item.発注数量 * item.発注単価,
        発注方法: 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: 'supplier-001',
        発注理由: 'AI需要予測に基づく発注',
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      const result = await window.aivicApi.save(9, orderData); // 発注データテーブル
      if (result) {
        results.push({ success: true, product: item.商品名 });
      } else {
        results.push({ success: false, product: item.商品名 });
      }
    }

    const successCount = results.filter(r => r.success).length;
    const failCount = results.filter(r => !r.success).length;

    if (failCount === 0) {
      alert(`発注が完了しました。\n発注件数: ${successCount}件`);
    } else {
      alert(`発注が完了しました。\n成功: ${successCount}件\n失敗: ${failCount}件`);
    }

    // 画面を更新
    updateDisplay();
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(orderItems) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const detailsDiv = container.querySelector('#confirm-details');

    let totalAmount = 0;
    const itemsHtml = orderItems.map(item => {
      const amount = item.発注数量 * item.発注単価;
      totalAmount += amount;
      return `
        <div style="display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid var(--border);">
          <span>${item.商品名}</span>
          <span>${item.発注数量}個 × ¥${item.発注単価.toLocaleString()} = ¥${amount.toLocaleString()}</span>
        </div>
      `;
    }).join('');

    detailsDiv.innerHTML = `
      <div style="margin-bottom: 20px;">
        <h4 style="color: var(--text); margin-bottom: 10px;">発注内容</h4>
        ${itemsHtml}
        <div style="display: flex; justify-content: space-between; padding: 12px 0; font-weight: bold; color: var(--text); border-top: 2px solid var(--border); margin-top: 10px;">
          <span>合計金額</span>
          <span>¥${totalAmount.toLocaleString()}</span>
        </div>
      </div>
    `;

    dialog.classList.remove('hidden');

    // 発注実行ボタンにデータを保存
    container.querySelector('#btn-execute-order').orderItems = orderItems;
  }

  // 初期データ読み込み
  async function initialize() {
    await loadStoreData();
    await loadProductData();
    await loadDemandForecastData();
  }

  // イベントリスナー設定

  // 表示更新ボタン
  container.querySelector('#btn-filter').addEventListener('click', updateDisplay);

  // 店舗選択変更時
  container.querySelector('#store-select').addEventListener('change', updateDisplay);

  // 発注日付変更時
  container.querySelector('#order-date').addEventListener('change', updateDisplay);

  // カテゴリフィルター変更時
  container.querySelector('#category-filter').addEventListener('change', updateDisplay);

  // 全選択ボタン
  container.querySelector('#btn-select-all').addEventListener('click', function() {
    const checkboxes = container.querySelectorAll('.order-checkbox');
    const allChecked = Array.from(checkboxes).every(cb => cb.checked);

    checkboxes.forEach(cb => {
      cb.checked = !allChecked;
    });

    updateSummary();
    updateBulkOrderButton();
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    const selectedItems = [];
    const checkboxes = container.querySelectorAll('.order-checkbox:checked');
    let hasError = false;

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);

      if (!validateQuantity(quantityInput)) {
        hasError = true;
        return;
      }

      const quantity = parseInt(quantityInput.value);
      const product = currentOrderData.find(p => p.商品ID === productId);

      if (product) {
        selectedItems.push({
          商品ID: product.商品ID,
          商品名: product.商品名,
          発注数量: quantity,
          予測数量: product.予測数量,
          発注単価: product.発注単価
        });
      }
    });

    if (hasError) {
      showError('入力内容にエラーがあります');
      return;
    }

    if (selectedItems.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    showOrderConfirmDialog(selectedItems);
  });

  // 個別発注実行ボタン
  container.addEventListener('click', function(e) {
    const singleOrderBtn = e.target.closest('.single-order-btn');
    if (singleOrderBtn) {
      const productId = singleOrderBtn.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const storeId = container.querySelector('#store-select').value;
      const orderDate = container.querySelector('#order-date').value;

      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      if (!orderDate) {
        showError('発注日付を選択してください');
        return;
      }

      if (!validateQuantity(quantityInput)) {
        showError('発注数量を正しく入力してください');
        return;
      }

      const quantity = parseInt(quantityInput.value);
      const product = currentOrderData.find(p => p.商品ID === productId);

      if (product) {
        const orderItems = [{
          商品ID: product.商品ID,
          商品名: product.商品名,
          発注数量: quantity,
          予測数量: product.予測数量,
          発注単価: product.発注単価
        }];

        showOrderConfirmDialog(orderItems);
      }
    }
  });

  // ダイアログ関連イベント
  container.querySelector('#close-dialog').addEventListener('click', function() {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-cancel-order').addEventListener('click', function() {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-execute-order').addEventListener('click', async function() {
    const orderItems = this.orderItems;
    if (orderItems) {
      container.querySelector('#order-confirm-dialog').classList.add('hidden');
      await executeOrder(orderItems);
    }
  });

  // ダイアログ外クリックで閉じる
  container.querySelector('#order-confirm-dialog').addEventListener('click', function(e) {
    if (e.target === this) {
      this.classList.add('hidden');
    }
  });

  // 初期化実行
  initialize();
}
